const rows = $input.first().json.data;

const TREND_MIN_COUNT = 3;

function bump(map, key) { if (key) map[key] = (map[key] || 0) + 1; }

const categoryCounts = {};
const issueTagCounts = {};
const sentimentCounts = { Positive: 0, Neutral: 0, Negative: 0 };
const severityCounts = { Low: 0, Medium: 0, High: 0 };
const categoryEvidence = {};
const issueTagEvidence = {};
const mixedOrUnclearRegister = [];

for (const r of rows) {
  bump(categoryCounts, r.category);
  bump(issueTagCounts, r.issue_tag);
  bump(sentimentCounts, r.sentiment);
  if (r.severity && r.severity !== 'N/A') bump(severityCounts, r.severity);

  (categoryEvidence[r.category] ??= []).push({ feedback_id: r.feedback_id, evidence_quote: r.evidence_quote, sentiment: r.sentiment, severity: r.severity });
  (issueTagEvidence[r.issue_tag] ??= []).push({ feedback_id: r.feedback_id, category: r.category, evidence_quote: r.evidence_quote, sentiment: r.sentiment });

  if (r.mixed_signal || r.confidence === 'low' || r.category === 'Other') {
    mixedOrUnclearRegister.push({
      feedback_id: r.feedback_id,
      category: r.category,
      secondary_category: r.secondary_category || null,
      secondary_note: r.secondary_note || null,
      confidence: r.confidence,
      rationale: r.rationale,
      reason: r.mixed_signal ? 'mixed_signal' : (r.confidence === 'low' ? 'low_confidence' : 'uncategorised_other')
    });
  }
}

const categoryTrends = Object.entries(categoryCounts).map(([category, count]) => ({
  category, count, is_pattern: count >= TREND_MIN_COUNT, evidence: categoryEvidence[category]
})).sort((a,b) => b.count - a.count);

const issueTagTrends = Object.entries(issueTagCounts).map(([issue_tag, count]) => ({
  issue_tag, count, is_pattern: count >= TREND_MIN_COUNT, evidence: issueTagEvidence[issue_tag]
})).sort((a,b) => b.count - a.count);

return [{
  json: {
    run_timestamp: new Date().toISOString(),
    total_feedback_analysed: rows.length,
    trend_min_count_threshold: TREND_MIN_COUNT,
    category_counts: categoryCounts,
    issue_tag_counts: issueTagCounts,
    sentiment_counts: sentimentCounts,
    severity_counts: severityCounts,
    category_trends: categoryTrends,
    issue_tag_trends: issueTagTrends,
    mixed_or_unclear_register: mixedOrUnclearRegister,
    classified_feedback: rows
  }
}];

const staticData = $getWorkflowStaticData('global');
const previousBaseline = staticData.urbanmart_baseline || { category_counts: {}, issue_tag_counts: {}, run_timestamp: null };

return [{
  json: {
    ...$input.first().json,
    previous_baseline: previousBaseline
  }
}];

const current = $input.first().json;
const prevCat = current.previous_baseline.category_counts || {};
const prevTag = current.previous_baseline.issue_tag_counts || {};

function deltaFor(currentCounts, prevCounts) {
  const keys = new Set([...Object.keys(currentCounts), ...Object.keys(prevCounts)]);
  const out = [];
  for (const k of keys) {
    const now = currentCounts[k] || 0;
    const before = prevCounts[k] || 0;
    out.push({
      key: k,
      count_now: now,
      count_before: before,
      delta: now - before,
      status: before === 0 && now > 0 ? 'new' : (now > before ? 'worsening' : (now < before ? 'improving' : 'unchanged'))
    });
  }
  return out.sort((a,b) => Math.abs(b.delta) - Math.abs(a.delta));
}

const category_delta = deltaFor(current.category_counts, prevCat);
const issue_tag_delta = deltaFor(current.issue_tag_counts, prevTag);
const has_prior_baseline = !!current.previous_baseline.run_timestamp;

return [{
  json: {
    ...current,
    has_prior_baseline,
    category_delta,
    issue_tag_delta
  }
}];

const trend = $('Agent 2 - Trend and Pattern Analyst').first().json.output || $('Agent 2 - Trend and Pattern Analyst').first().json;
const anomaly = $('Agent 3 - Emerging and Anomaly Agent').first().json.output || $('Agent 3 - Emerging and Anomaly Agent').first().json;
const evidence = $('Compute Deltas vs Baseline').first().json;

return [{
  json: {
    trend_findings: trend,
    anomaly_findings: anomaly,
    total_feedback_analysed: evidence.total_feedback_analysed,
    sentiment_counts: evidence.sentiment_counts,
    severity_counts: evidence.severity_counts,
    retry_note: $json.retry_note || null
  }
}];

const recOutput = $('Agent 4: Recommendation Agent').first().json.output || $('Agent 4: Recommendation Agent').first().json;
const evidence = $('Compute Deltas vs Baseline').first().json;
const realIds = new Set(evidence.classified_feedback.map(r => r.feedback_id));

const invalidCitations = [];
for (const rec of (recOutput.recommendations || [])) {
  for (const id of (rec.evidence_feedback_ids || [])) {
    if (!realIds.has(id)) invalidCitations.push({ recommendation: rec.recommendation, invalid_id: id });
  }
}

return [{
  json: {
    recommendations: recOutput,
    integrity_check_passed: invalidCitations.length === 0,
    invalid_citations: invalidCitations
  }
}];

return JSON.stringify({
  categories: {
    "Delivery": "Delivery time, tracking, delivery charges, damaged delivery, or delivery promises",
    "Product Quality": "Damaged, defective, unreliable, or poor-quality products",
    "Pricing": "Expensive products, discounts, affordability, or value for money",
    "Product Availability": "Out-of-stock items, unavailable products, or limited selection",
    "Customer Service": "Customer support, complaint handling, response times, and problem resolution",
    "Staff Behaviour": "Helpfulness, professionalism, attitude, or behaviour of store employees",
    "Store Experience": "Cleanliness, queues, billing counters, layout, or the physical shopping experience",
    "Website / App": "Website errors, mobile app problems, checkout failures, speed, or usability",
    "Other": "Feedback that does not clearly fit one of the available categories"
  },
  sentiments: {
    "Positive": "The customer expresses satisfaction or a positive experience",
    "Neutral": "The customer is neither clearly satisfied nor dissatisfied",
    "Negative": "The customer expresses dissatisfaction, frustration, or a poor experience"
  },
  severities: {
    "Low": "A minor issue with limited impact on the customer experience",
    "Medium": "A meaningful issue that negatively affects the customer experience",
    "High": "A serious issue, repeated failure, or problem with significant customer impact"
  }
});

const evidence = $('Compute Deltas vs Baseline').first().json;
const merged = $('Merge Trend and Anomaly Insights').first().json;
const check = $('Evidence Integrity Check').first().json;
const retryStatus = $('Check Retry Cap').first().json;

return [{
  json: {
    report_date: new Date().toISOString().slice(0,10),
    total_feedback_analysed: evidence.total_feedback_analysed,
    sentiment_counts: evidence.sentiment_counts,
    severity_counts: evidence.severity_counts,
    mixed_or_unclear_register: evidence.mixed_or_unclear_register,
    trend_findings: merged.trend_findings,
    anomaly_findings: merged.anomaly_findings,
    recommendations: check.recommendations,
    guardrail_retry_used: retryStatus.retry_attempt > 0,
    guardrail_validation_forced_through: retryStatus.validation_forced_through,
    approval_status: 'PENDING_MANAGEMENT_REVIEW'
  }
}];

const evidence = $('Compute Deltas vs Baseline').first().json;
const staticData = $getWorkflowStaticData('global');

staticData.urbanmart_baseline = {
  category_counts: evidence.category_counts,
  issue_tag_counts: evidence.issue_tag_counts,
  run_timestamp: evidence.run_timestamp
};

// $json here is the Status-sheet row written by 'Record Status: APPROVED';
// pull the actual approval response from the Gmail node instead.
const approval = $('Send Report for Management Approval').first().json;

return [{
  json: {
    baseline_updated: true,
    stored_run_timestamp: evidence.run_timestamp,
    status_sheet_row: $json,
    final_report: approval
  }
}];

// $json here is the Status-sheet row written by 'Record Status: CHANGES REQUESTED';
// read the manager's response from the Gmail node.
const approval = $('Send Report for Management Approval').first().json;

return [{
  json: {
    approval_status: 'CHANGES_REQUESTED_BY_MANAGEMENT',
    reviewed_at: new Date().toISOString(),
    reviewer_note: approval.text || approval.data?.text || 'See approval tool response',
    status_sheet_row: $json,
    final_report: approval
  }
}];

