const id = (query || '').trim().toUpperCase();
const rows = $('Compute Deltas vs Baseline').first().json.classified_feedback || [];
const found = rows.find(r => r.feedback_id === id);
if (!found) {
  return `No feedback found with id "${id}". Valid ids look like F001-F030 for the sample dataset, or channel-specific ids for live feedback.`;
}
return JSON.stringify(found);

return JSON.stringify({
  business: "UrbanMart operates physical retail stores and an online shopping platform",
  main_customer_channels: "Physical stores, website, mobile app, online surveys, and email",
  delivery_promise: "Standard orders are normally delivered within 2 to 3 working days",
  customer_service_goal: "Customer issues should receive an initial response within 24 hours",
  management_priority: "Improve customer satisfaction and encourage repeat purchases",
  improvement_approach: "Management prefers practical improvements that can initially be implemented without major infrastructure investment",
  decision_authority: "AI can analyse information and recommend improvements, but management must approve operational changes"
});

const attempt = ($json.retry_attempt || 0) + 1;
const guardrail = $('Agent 5: Guardrail / QA + retry loop').first().json.output || $('Agent 5: Guardrail / QA + retry loop').first().json;
const merged = $('Merge Trend and Anomaly Insights').first().json;

return [{
  json: {
    ...merged,
    retry_attempt: attempt,
    retry_note: guardrail.feedback_for_retry
  }
}];

// Pull the guardrail's verdict for THIS pass
const guardrail = $('Agent 5: Guardrail / QA + retry loop').first().json.output || $('Agent 5: Guardrail / QA + retry loop').first().json;

// Reliably read how many retries have already happened. We look this up from the
// 'Prepare Retry (Max 1x)' node directly (rather than relying on retry_attempt riding along
// through item json), because AI Agent nodes replace their item's json with just their own
// output and silently drop custom fields like retry_attempt along the way.
let retryAttempt = 0;
try {
  const prep = $('Prepare Retry (Max 1x)').first();
  retryAttempt = (prep && prep.json && prep.json.retry_attempt) || 0;
} catch (e) {
  retryAttempt = 0; // node hasn't run yet in this execution - this is the first attempt
}

const MAX_RETRIES = 1;
const passed = !!guardrail.passed;
const retriesExhausted = retryAttempt >= MAX_RETRIES;

return [{
  json: {
    passed,
    feedback_for_retry: guardrail.feedback_for_retry || null,
    retry_attempt: retryAttempt,
    retries_exhausted: retriesExhausted,
    should_proceed: passed || retriesExhausted,
    validation_forced_through: !passed && retriesExhausted
  }
}];

// Reset the per-run accumulator that will collect Agent 1's classified output,
// one item at a time, as the loop below processes them individually for rate-limit pacing.
const staticData = $getWorkflowStaticData('global');
staticData.urbanmart_classified_accumulator = [];
return $input.all();

// The loop node's 'done' output only replays whatever it originally received -
// it does NOT automatically collect the classified results we produced during looping.
// So we push each classified item into workflow static data here, right after Agent 1 runs,
// and read the full collected list back out once the loop finishes.
const staticData = $getWorkflowStaticData('global');
const classified = $json.output || $json;
staticData.urbanmart_classified_accumulator = staticData.urbanmart_classified_accumulator || [];
staticData.urbanmart_classified_accumulator.push(classified);
return [{ json: { _looped: true } }];

// Loop is finished - pull out every classified item collected along the way and
// re-expand them into individual n8n items, exactly the shape 'Combine Classified
// Feedbacks' (Aggregate node) expects.
const staticData = $getWorkflowStaticData('global');
const rows = staticData.urbanmart_classified_accumulator || [];
return rows.map(r => ({ json: r }));

const md = $json.output || '';

function escapeHtml(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function inline(text) {
  let t = escapeHtml(text);
  // bold
  t = t.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  // italic (single asterisk, not part of a bullet marker)
  t = t.replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, '$1<em>$2</em>');
  return t;
}

const lines = md.split('\n');
let html = '';
let inList = null; // 'ul' | 'ol' | null
let paragraphBuffer = [];

function flushParagraph() {
  if (paragraphBuffer.length) {
    html += `<p style="margin:0 0 12px 0; line-height:1.55; color:#2b2b2b;">${paragraphBuffer.join(' ')}</p>`;
    paragraphBuffer = [];
  }
}
function closeList() {
  if (inList) {
    html += `</${inList}>`;
    inList = null;
  }
}

for (const rawLine of lines) {
  const line = rawLine.trim();

  if (line === '') {
    flushParagraph();
    closeList();
    continue;
  }

  // Warning callout line
  if (line.startsWith('⚠')) {
    flushParagraph();
    closeList();
    html += `<div style="background:#fff4e5; border-left:4px solid #d97706; padding:12px 16px; margin:16px 0; border-radius:4px; color:#7c4a03; font-weight:600;">${inline(line)}</div>`;
    continue;
  }

  // Horizontal rule
  if (/^-{3,}$/.test(line)) {
    flushParagraph();
    closeList();
    html += '<hr style="border:none; border-top:1px solid #e2e2e2; margin:20px 0;">';
    continue;
  }

  // Headers
  let m = line.match(/^(#{1,4})\s+(.*)$/);
  if (m) {
    flushParagraph();
    closeList();
    const level = m[1].length;
    const sizes = { 1: '22px', 2: '19px', 3: '16px', 4: '14px' };
    const colors = { 1: '#1a1a1a', 2: '#1a1a1a', 3: '#333333', 4: '#444444' };
    html += `<h${Math.min(level + 1, 4)} style="font-size:${sizes[level] || '14px'}; color:${colors[level] || '#333'}; margin:22px 0 10px 0; font-family:Arial,Helvetica,sans-serif;">${inline(m[2])}</h${Math.min(level + 1, 4)}>`;
    continue;
  }

  // Bullet list
  m = line.match(/^[-*]\s+(.*)$/);
  if (m) {
    flushParagraph();
    if (inList !== 'ul') { closeList(); html += '<ul style="margin:0 0 12px 0; padding-left:22px;">'; inList = 'ul'; }
    html += `<li style="margin-bottom:6px; line-height:1.5; color:#2b2b2b;">${inline(m[1])}</li>`;
    continue;
  }

  // Numbered list
  m = line.match(/^\d+\.\s+(.*)$/);
  if (m) {
    flushParagraph();
    if (inList !== 'ol') { closeList(); html += '<ol style="margin:0 0 12px 0; padding-left:22px;">'; inList = 'ol'; }
    html += `<li style="margin-bottom:6px; line-height:1.5; color:#2b2b2b;">${inline(m[1])}</li>`;
    continue;
  }

  // Otherwise: part of a paragraph
  closeList();
  paragraphBuffer.push(inline(line));
}
flushParagraph();
closeList();

const wrapped = `
<div style="font-family:Arial,Helvetica,sans-serif; max-width:680px; margin:0 auto; padding:24px; color:#2b2b2b;">
  <div style="border-bottom:2px solid #1a1a1a; padding-bottom:12px; margin-bottom:20px;">
    <h1 style="font-size:22px; margin:0; color:#1a1a1a;">UrbanMart Customer Feedback Report</h1>
  </div>
  ${html}
</div>
`.trim();

return [{ json: { management_report_html: wrapped } }];

const id = (query || '').trim().toUpperCase();
const rows = $('Compute Deltas vs Baseline').first().json.classified_feedback || [];
const found = rows.find(r => r.feedback_id === id);
if (!found) {
  return `No feedback found with id "${id}". Valid ids look like F001-F030 for the sample dataset, or channel-specific ids for live feedback.`;
}
return JSON.stringify(found);

return $input.all().map(({ json: r }) => ({
  json: {
    feedback_id: r.feedback_id || `SUR-${r.row_number || Date.now()}`,
    date: new Date(r.date || r.Timestamp || Date.now()).toISOString().slice(0, 10),
